SELECT int8 = uint16 AS c0, toTypeName(int8 = uint16) AS t0, int8 != uint16 AS c1, toTypeName(int8 != uint16) AS t1, int8 < uint16 AS c2, toTypeName(int8 < uint16) AS t2, int8 <= uint16 AS c3, toTypeName(int8 <= uint16) AS t3, int8 > uint16 AS c4, toTypeName(int8 > uint16) AS t4, int8 >= uint16 AS c5, toTypeName(int8 >= uint16) AS t5 FROM he24.numeric ORDER BY row_id
